  p_old jsonb,
  p_new jsonb
)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $$
  WITH keys AS (
    SELECT key FROM jsonb_object_keys(coalesce(p_old, '{}'::jsonb)) AS k(key)
    UNION
    SELECT key FROM jsonb_object_keys(coalesce(p_new, '{}'::jsonb)) AS k(key)
  )
  SELECT coalesce(
    jsonb_object_agg(
      key,
      jsonb_build_object(
        'old', p_old -> key,
        'new', p_new -> key
      )
    ) FILTER (WHERE (p_old -> key) IS DISTINCT FROM (p_new -> key)),
    '{}'::jsonb
  )
  FROM keys
$$;
